import {
  showErrorMessage,
  showSuccessMessage,
} from '/static/js/common/notification.prod.js';
export function debounce(e, o = 500) {
  let t;
  return function (...r) {
    (clearTimeout(t),
      (t = setTimeout(() => {
        e.apply(this, r);
      }, o)));
  };
}
export function checkEmail(e) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);
}
export function validatePassword(e) {
  return e.length < 8
    ? 'The password is too short.'
    : /\d/.test(e)
      ? /[a-zA-Z]/.test(e)
        ? /[^a-zA-Z0-9\s]/.test(e)
          ? null
          : 'Enter a special character - !@#$%^&*(){}[],./'
        : 'Enter an alphabet letter A-Z.'
      : 'Enter a number 0-9.';
}
export function parseDuration(e) {
  const o = e.match(/^P(?:(\d+)D)?T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/);
  if (!o) return 0;
  return (
    86400 * Number(o[1] || 0) +
    3600 * Number(o[2] || 0) +
    60 * Number(o[3] || 0) +
    Number(o[4] || 0)
  );
}
const COOLDOWN_KEY = 'login_cooldown_until';
let Timeout = null;
export function startCooldown(e) {
  const o = Date.now() + 1e3 * e;
  (localStorage.setItem(COOLDOWN_KEY, o),
    clearTimeout(Timeout),
    updateCooldown());
}
export function updateCooldown() {
  clearTimeout(Timeout);
  const e = $('#formButton'),
    o = Number(localStorage.getItem(COOLDOWN_KEY));
  if (!o) return void e.prop('disabled', !1);
  const t = Math.ceil((o - Date.now()) / 1e3);
  if (t <= 0)
    return (
      localStorage.removeItem(COOLDOWN_KEY),
      e.prop('disabled', !1),
      showSuccessMessage('Lockdown Lifted', 'Redirecting you'),
      void window.location.reload()
    );
  const r = Math.floor(t / 60),
    n = t % 60;
  (e.prop('disabled', !0),
    showErrorMessage(
      'Lockdown Initiated',
      `Try again after ${r} minute(s) and ${n} second(s)`
    ),
    (Timeout =
      t < 60
        ? setTimeout(updateCooldown, 1e3 * t)
        : setTimeout(updateCooldown, 6e4)));
}
